import {finishes,accessories,products,compatibility} from './catalog-data.js';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}};
// Event payloads use only allowlisted names and route paths, never contact fields or query strings.
const events=new Set(['homepage_cta_click','kitchen_package_view','product_detail_view','customization_start','configuration_complete','estimator_start','estimator_complete','accessory_added','project_saved','quote_request_start','quote_brief_prepared','order_flow_started','whole_kitchen_path','individual_cabinet_path','accessories_only_path','basic_cabinet_selected','basic_cabinet_kept','storage_recommendation_viewed','accessory_recommendation_selected','accessory_removed','bundle_discount_applied']);
export function track(name){if(!events.has(name))return;const event={event:name,path:location.pathname};window.dispatchEvent(new CustomEvent('amber:analytics',{detail:event}));if(Array.isArray(window.dataLayer))window.dataLayer.push(event);}
window.amberTrack=track;
if(location.pathname==='/kabbie/kitchens/')track('kitchen_package_view');
if(/^\/kabbie\/cabinets\/(?!base\/|wall\/|tall\/)[^/]+\/$/.test(location.pathname))track('product_detail_view');
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&location.pathname==='/kabbie/'&&a.classList.contains('btn'))track('homepage_cta_click');});
const form=$('#kitchen-estimator');
if(form){
 const key='amber-kitchen-estimate-v1',params=new URLSearchParams(location.search);
 const steps=[['project','What are you planning?',['New construction','Full renovation','Cabinet replacement','Additional storage']],['layout','What is your kitchen layout?',['One wall','Galley','L-shaped','U-shaped','Island kitchen','Peninsula kitchen','Not sure']],['size','How much space are you working with?',['Under 100 sq ft','100–199 sq ft','200+ sq ft','Enter measurements','Not sure']],['finish','Which finish feels like home?',[...finishes.map(f=>f.name),'Undecided']],['storage','What would make the everyday easier?',accessories.map(a=>a.name)],['design','Would you like design assistance?',['Yes','No','Not sure']]];
 let state={storage:[],...read(key,{})},step=0;
 if(['Small','Medium','Large'].includes(state.size))delete state.size;
 const legacySizes={Small:'Under 100 sq ft',Medium:'100–199 sq ft',Large:'200+ sq ft'};if(legacySizes[params.get('size')])params.set('size',legacySizes[params.get('size')]);
 for(const k of ['size','layout'])if(steps.find(s=>s[0]===k)[2].includes(params.get(k)))state[k]=params.get(k);
 const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{$('#estimate-error').hidden=false;$('#estimate-error').textContent='Device storage is unavailable. Keep this page open and copy your planning summary before leaving.';return false;}};
 const summary=()=>steps.map(([k,title])=>`<div><strong>${esc(title)}</strong><p>${esc(Array.isArray(state[k])?(state[k].join(', ')||'No upgrades selected'):state[k]||'To choose')}</p></div>`).join('');
 function render(){
 $('#estimate-summary').innerHTML=summary();$('#estimate-back').hidden=step===0;$('#estimate-next').hidden=step===6;
 $('#estimate-progress').textContent=step<6?`Step ${step+1} of 6`:'Your planning scope is ready';
 if(step===6){$('#estimate-step').innerHTML=`<h2 tabindex="-1">A clearer brief. A personalized quote.</h2><p>Your choices are saved alongside your cabinet project.</p><dl class="estimate-costs">${['Cabinet units','Finish & material upgrades','Interior storage','Design assistance','Delivery & installation','Estimated total'].map(v=>`<dt>${v}</dt><dd>Quote required</dd>`).join('')}</dl><p>Tax, countertops and appliances are excluded unless expressly quoted. There are no verified item prices available to calculate a total.</p><div class="inline-actions"><a class="btn" href="/kabbie/start-order/?fromEstimate=1&help=design">Get My Personalized Quote</a><a class="textlink" href="/kabbie/start-order/?fromEstimate=1">Add or review cabinets →</a></div><button class="textlink" type="button" id="edit-estimate">Edit my planning choices</button>`;$('#edit-estimate').onclick=()=>{step=0;render();};return;}
 const [k,title,values]=steps[step],multiple=k==='storage';
 $('#estimate-next').textContent=step===5?'Review my estimate scope':'Continue';
 $('#estimate-step').innerHTML=`<h2 tabindex="-1">${title}</h2>${multiple?'<p>Choose any that interest you, or continue without upgrades. Exact cabinet compatibility is checked in the configurator.</p>':''}<fieldset class="estimate-choices"><legend class="visually-hidden">${title}</legend>${values.map(v=>{const f=finishes.find(f=>f.name===v);return `<label class="estimate-choice"><input type="${multiple?'checkbox':'radio'}" name="${k}" value="${esc(v)}" ${multiple?state.storage.includes(v)?'checked':'':state[k]===v?'checked':''}>${f?`<span class="swatch" style="background:${f.swatch}"></span>`:''}<span>${v}</span></label>`;}).join('')}</fieldset>${k==='size'?`<label class="commerce-field" id="estimate-measurement-field" ${state.size==='Enter measurements'?'':'hidden'}>Room dimensions or sketch notes (optional)<textarea name="measurements" maxlength="1000" rows="3">${esc(state.measurements)}</textarea></label>`:''}`;
 }
 form.addEventListener('change',e=>{if(e.target.name==='measurements')return;const k=steps[step][0];state[k]=k==='storage'?[...form.querySelectorAll('input:checked')].map(i=>i.value):e.target.value;persist();$('#estimate-summary').innerHTML=summary();if(k==='size')$('#estimate-measurement-field').hidden=state.size!=='Enter measurements';});
 form.addEventListener('input',e=>{if(e.target.name==='measurements'){state.measurements=e.target.value;persist();}});
 form.addEventListener('submit',e=>{e.preventDefault();const k=steps[step]?.[0];if(step<6&&k!=='storage'&&!state[k]){$('#estimate-error').hidden=false;$('#estimate-error').textContent='Choose an option to continue.';return;}$('#estimate-error').hidden=true;persist();step++;render();$('#estimate-step h2')?.focus({preventScroll:true});if(step===6)track('estimator_complete');});
 $('#estimate-back').onclick=()=>{step=Math.max(0,step-1);render();};track('estimator_start');render();
}
// A project shortcut keeps discovery and review connected on all pages.
const project=read('amber-cabinet-project-v1',{});
if(project.project?.length&&location.pathname!=='/kabbie/start-order/'){
 const a=document.createElement('a');a.className='project-shortcut';a.href='/kabbie/start-order/';a.textContent=`My cabinet plan · ${project.project.reduce((n,c)=>n+Number(c.quantity||1),0)} units →`;document.body.append(a);
}

if($('#storage-explorer-preview')){const show=id=>{const a=accessories.find(a=>a.id===id);if(!a)return;document.querySelectorAll('[data-explore-storage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.exploreStorage===id)));$('#storage-explorer-preview').innerHTML=`<img src="/kabbie/assets/${a.image}" alt="${esc(a.name)} illustrative accessory reference" loading="lazy"><p class="caption">Accessory reference image · final product and fit require confirmation</p>`;const matches=products.filter(p=>p.widths.some(w=>compatibility(p,w,a).ok));$('#storage-explorer-copy').innerHTML=`<h3>${esc(a.purpose)}</h3><p>${esc(a.name)} helps organize this storage need within your chosen cabinet.</p><p class="caption">Planning matches: ${matches.map(p=>esc(p.name)).join(', ')||'Ask for a custom review'}. Exact internal clearance and hardware need confirmation.</p><p><strong>Upgrade price: Quote required</strong></p><a class="btn outline" href="/kabbie/cabinets/?storage=${a.id}">Find compatible cabinets →</a>`;};document.querySelectorAll('[data-explore-storage]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.exploreStorage)));show(accessories[0].id);}
const reveal=document.querySelector('[data-cabinet-reveal]');
if(reveal){
 reveal.querySelectorAll('[data-reveal-accessory]').forEach(button=>button.addEventListener('click',()=>{reveal.querySelectorAll('[data-reveal-accessory]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const name=button.querySelector('span').textContent;$('#reveal-accessory-image',reveal).src='/kabbie/assets/'+button.dataset.revealImage;$('#reveal-accessory-image',reveal).alt=name+', illustrative accessory reference';$('#reveal-title',reveal).textContent=name;$('#reveal-copy',reveal).textContent=button.dataset.revealCopy;$('#reveal-fit',reveal).textContent=button.dataset.revealFit;$('#reveal-match',reveal).href='/kabbie/cabinets/?storage='+button.dataset.revealAccessory;$('#reveal-photo-label',reveal).textContent=name+' · accessory reference';}));
}
const peek=document.querySelector('.storage-peek');
if(peek){const options={rollout:['accessory-shelves.png','Roll-out shelves bring cookware forward in a door base cabinet.','Illustrative roll-out shelves holding cookware inside a base cabinet'],divider:['accessory-drawers.png','Drawer dividers give utensils their own place in a drawer base cabinet.','Illustrative drawer dividers organizing utensils'],waste:['accessory-bins.png','Pull-out bins keep trash and recycling tucked inside a door base cabinet.','Illustrative pull-out waste and recycling bins inside a base cabinet']};peek.querySelectorAll('[data-peek]').forEach(button=>button.addEventListener('click',()=>{const [image,copy,alt]=options[button.dataset.peek];peek.querySelectorAll('[data-peek]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('.storage-peek-image',peek).src='/kabbie/assets/'+image;$('.storage-peek-image',peek).alt=alt;$('.storage-peek-copy',peek).textContent=copy;$('.storage-peek-link',peek).href='/kabbie/cabinets/?storage='+button.dataset.peek;}));}
const serviceMap=$('#home-service-map');
if(serviceMap){
 const communities=JSON.parse(serviceMap.dataset.communities);
 const linkFor=c=>'/kabbie/locations/'+c.name.toLowerCase().replaceAll(' ','-')+'/';
 if(window.L){
  const L=window.L;serviceMap.innerHTML='';const map=L.map(serviceMap,{scrollWheelZoom:false,dragging:!L.Browser.mobile,tapHold:true});
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);
  const markers=communities.map((c,i)=>L.marker([c.lat,c.lng],{title:c.name,alt:c.name,icon:L.divIcon({className:'community-map-marker',html:'<span style="background:'+([...document.querySelectorAll('[data-map-region]')].find(r=>r.dataset.mapRegion.split(',').includes(String(i)))?.style.getPropertyValue('--region-color')||'#354335')+'">'+(i+1)+'</span>',iconSize:[28,28],iconAnchor:[14,14]})}).addTo(map).bindTooltip(c.name).bindPopup('<strong>'+esc(c.name)+'</strong><br><a href="'+linkFor(c)+'">Explore '+esc(c.name)+' cabinetry →</a>'));
  const bounds=L.latLngBounds(communities.map(c=>[c.lat,c.lng]));map.fitBounds(bounds,{padding:[35,35]});
  document.querySelectorAll('[data-map-community]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.mapCommunity);map.panTo(markers[i].getLatLng(),{animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});markers[i].openPopup();document.querySelectorAll('[data-map-community]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
  document.querySelectorAll('[data-map-region]').forEach(region=>region.addEventListener('toggle',()=>{if(!region.open)return;document.querySelectorAll('[data-map-region]').forEach(other=>{if(other!==region)other.open=false;});map.closePopup();map.fitBounds(L.latLngBounds(region.dataset.mapRegion.split(',').map(i=>markers[Number(i)].getLatLng())),{padding:[50,50],maxZoom:11,animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});}));
  const reset=L.control({position:'topright'});reset.onAdd=()=>{const button=L.DomUtil.create('button','map-show-all');button.type='button';button.textContent='Show all areas';L.DomEvent.disableClickPropagation(button);button.onclick=()=>{map.closePopup();map.fitBounds(bounds,{padding:[35,35],animate:false});};return button;};reset.addTo(map);
  new ResizeObserver(()=>{map.invalidateSize();}).observe(serviceMap);
 }else document.querySelectorAll('[data-map-community]').forEach(button=>button.onclick=()=>location.href=linkFor(communities[Number(button.dataset.mapCommunity)]));
}
const summaryDisclosure=document.querySelector('.project-summary-disclosure');
if(summaryDisclosure){const mobileSummary=matchMedia('(max-width:760px)');const update=()=>summaryDisclosure.open=!mobileSummary.matches;update();mobileSummary.addEventListener('change',update);}
const welcome=document.querySelector('.welcome-home');
if(welcome){const details=[...welcome.querySelectorAll('.welcome-detail')];details.forEach(d=>d.addEventListener('toggle',()=>{if(d.open)details.forEach(other=>{if(other!==d)other.open=false;});}));document.addEventListener('keydown',e=>{if(e.key==='Escape')details.forEach(d=>d.open=false);});document.addEventListener('click',e=>{if(!e.target.closest('.welcome-detail'))details.forEach(d=>d.open=false);});const update=()=>{const current=welcome.querySelector('.hero-slide.is-active'),preview=welcome.querySelector('.welcome-finish-preview');if(current&&preview){preview.src=current.getAttribute('src');preview.alt=current.alt;}};new MutationObserver(update).observe(welcome.querySelector('.hero-slides'),{subtree:true,attributes:true,attributeFilter:['class']});}


const accessoryCatalog=document.querySelector('[data-accessory-catalog]');
if(accessoryCatalog){const cards=[...accessoryCatalog.querySelectorAll('[data-accessory-categories]')];let category='',item='';const update=()=>{let count=0;cards.forEach(card=>{const visible=(!category||card.dataset.accessoryCategories.split(' ').includes(category))&&(!item||card.dataset.accessoryItems.split(' ').includes(item));card.hidden=!visible;if(visible)count++;});accessoryCatalog.querySelectorAll('[data-accessory-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accessoryCategory===category)));accessoryCatalog.querySelectorAll('[data-accessory-item]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accessoryItem===item)));accessoryCatalog.querySelector('[data-accessory-count]').textContent=count+' accessory idea'+(count===1?'':'s');accessoryCatalog.querySelector('[data-accessory-empty]').hidden=count>0;};accessoryCatalog.querySelectorAll('[data-accessory-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.accessoryCategory;update();}));accessoryCatalog.querySelectorAll('[data-accessory-item]').forEach(b=>b.addEventListener('click',()=>{item=b.dataset.accessoryItem;update();}));accessoryCatalog.querySelector('[data-accessory-reset]').addEventListener('click',()=>{category='';item='';update();});}

const countTool=document.querySelector('[data-cabinet-count]');
if(countTool){const run=countTool.querySelector('#count-run'),width=countTool.querySelector('#count-width'),product=countTool.querySelector('#count-product'),link=countTool.querySelector('#count-plan');const update=()=>{const length=Number(run.value),w=Number(width.value),valid=run.value!==''&&Number.isFinite(length)&&length>=1&&length<=2400;countTool.querySelector('#count-error').hidden=valid;if(!valid){countTool.querySelector('#count-total').textContent='Check your run length';countTool.querySelector('#count-explanation').textContent='';link.hidden=true;return;}const n=Math.floor((length+.000001)/w),used=n*w,left=Math.round((length-used)*10)/10;countTool.querySelector('#count-total').textContent=n+' cabinet box'+(n===1?'':'es');countTool.querySelector('#count-explanation').textContent=n+' × '+w+'″ = '+used+'″ of cabinet width; '+left+'″ left before fitting allowances.';link.hidden=n===0;link.href='/kabbie/start-order/?product='+encodeURIComponent(product.value)+'&width='+w;};[run,width,product].forEach(el=>el.addEventListener('input',update));update();}
